<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import api from '../services/api.js'
import ExportButton from '../components/ExportButton.vue'
const route=useRoute(), userId=1, perPage=10
const periods=ref([]),workshops=ref([]),details=ref([]),media=ref([]),units=ref([])
const periodId=ref(null),targetGroup=ref('ALL'),selected=ref(null),edit=ref(null),page=ref(1),card=ref(null)
const loading=ref(true),saving=ref(false),deleting=ref(false),error=ref(''),editError=ref(''),success=ref('');let timer=null
const groups=[{value:'ALL',label:'Sve skupine'},{value:'STUDENTS',label:'Studenti'},{value:'TEACHERS',label:'Nastavnici'},{value:'PUBLIC',label:'Javnost'},{value:'EMPLOYEES',label:'Zaposlenici'},{value:'DOCTORAL_STUDENTS',label:'Doktorandi'}]
const filtered=computed(()=>workshops.value.filter(w=>Number(w.reporting_period_id)===Number(periodId.value)&&(targetGroup.value==='ALL'||w.target_group===targetGroup.value)))
const pages=computed(()=>Math.ceil(filtered.value.length/perPage)),shown=computed(()=>filtered.value.slice((page.value-1)*perPage,page.value*perPage))
const periodWorkshopIds=computed(()=>new Set(workshops.value.filter(w=>Number(w.reporting_period_id)===Number(periodId.value)).map(w=>Number(w.id))))
const periodDetails=computed(()=>details.value.filter(d=>periodWorkshopIds.value.has(Number(d.workshop_id)))),periodMedia=computed(()=>media.value.filter(m=>periodWorkshopIds.value.has(Number(m.workshop_id))))
const selectedDetails=computed(()=>details.value.find(d=>Number(d.workshop_id)===Number(selected.value?.id))||null),selectedMedia=computed(()=>media.value.filter(m=>Number(m.workshop_id)===Number(selected.value?.id)))
const optionalNumber=v=>v===''||v===null||v===undefined?null:Number(v),display=v=>v===null||v===undefined||v===''?'—':v
const groupLabel=v=>groups.find(g=>g.value===v)?.label||v||'—',date=v=>{if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?v:new Intl.DateTimeFormat('hr-HR').format(d)},dateInput=v=>v?String(v).slice(0,10):''
const unitName=id=>{const u=units.value.find(x=>Number(x.id)===Number(id));return u?u.short_name||u.name:'—'}
function url(v){if(!v)return null;if(v.startsWith('/uploads/'))return`${api.defaults.baseURL}${v}`;try{const u=new URL(v);return['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}}
function apiError(e,f){const x=e.response?.data?.errors;return Array.isArray(x)?x.join(' '):e.response?.data?.message||f}
function toast(m){success.value=m;if(timer)clearTimeout(timer);timer=setTimeout(()=>success.value='',4000)}
function choose(w){selected.value=w;edit.value=null;editError.value=''}
function startEdit(){const w=selected.value,d=selectedDetails.value;edit.value={workshop_name:w.workshop_name,workshop_leaders:w.workshop_leaders??'',organizational_unit_id:w.organizational_unit_id??'',target_group:w.target_group,participant_count:w.participant_count??'',location:w.location??'',held_on:dateInput(w.held_on),duration_hours:w.duration_hours??'',content_description:w.content_description??'',media_link:w.media_link??'',notes:w.notes??'',detail:d?{...d}:null,detailDeleted:false,media:selectedMedia.value.map(m=>({...m,published_on:dateInput(m.published_on)})),deletedMediaIds:[]}}
function cancel(){edit.value=null;editError.value=''}
function toggleDetail(){if(edit.value.detail){edit.value.detail=null;edit.value.detailDeleted=Boolean(selectedDetails.value);return}edit.value.detail=selectedDetails.value?{...selectedDetails.value}:{temporary:true,goals:'',learning_outcomes:'',work_methods:'',materials_resources:'',evaluation:''};edit.value.detailDeleted=false}
function addMedia(){edit.value.media.push({temporaryId:crypto.randomUUID(),workshop_name:edit.value.workshop_name,media_type:'',media_link:'',published_on:''})}
function removeMedia(m){if(!m.id){edit.value.media=edit.value.media.filter(x=>x.temporaryId!==m.temporaryId);return}if(confirm(`Želite li ukloniti medijsku objavu za „${m.workshop_name}”?`)){edit.value.deletedMediaIds.push(m.id);edit.value.media=edit.value.media.filter(x=>x.id!==m.id)}}
async function save(){const f=edit.value;editError.value='';if(!f.workshop_name.trim()||!f.target_group){editError.value='Naziv radionice i ciljana skupina su obavezni.';return}if(f.media.some(m=>!m.workshop_name.trim()||!m.media_link.trim())){editError.value='Naziv radionice i link obavezni su za svaku medijsku objavu.';return}saving.value=true;try{const response=await api.patch(`/api/workshops/${selected.value.id}`,{workshop_name:f.workshop_name.trim(),workshop_leaders:f.workshop_leaders.trim()||null,organizational_unit_id:optionalNumber(f.organizational_unit_id),target_group:f.target_group,participant_count:optionalNumber(f.participant_count),location:f.location.trim()||null,held_on:f.held_on||null,duration_hours:optionalNumber(f.duration_hours),content_description:f.content_description.trim()||null,media_link:f.media_link.trim()||null,notes:f.notes.trim()||null,updated_by:userId});let detailResponse=null;if(f.detail){const payload={goals:f.detail.goals?.trim()||null,learning_outcomes:f.detail.learning_outcomes?.trim()||null,work_methods:f.detail.work_methods?.trim()||null,materials_resources:f.detail.materials_resources?.trim()||null,evaluation:f.detail.evaluation?.trim()||null,updated_by:userId};detailResponse=f.detail.id?await api.patch(`/api/workshops/details/${f.detail.id}`,payload):await api.post('/api/workshops/details',{...payload,workshop_id:selected.value.id,created_by:userId})}else if(f.detailDeleted&&selectedDetails.value)await api.delete(`/api/workshops/details/${selectedDetails.value.id}`);const mediaResponses=await Promise.all(f.media.map(m=>m.id?api.patch(`/api/workshops/media/${m.id}`,{workshop_name:m.workshop_name.trim(),media_type:m.media_type.trim()||null,media_link:m.media_link.trim(),published_on:m.published_on||null,updated_by:userId}):api.post('/api/workshops/media',{workshop_id:selected.value.id,workshop_name:m.workshop_name.trim(),media_type:m.media_type.trim()||null,media_link:m.media_link.trim(),published_on:m.published_on||null,created_by:userId,updated_by:userId})));await Promise.all(f.deletedMediaIds.map(id=>api.delete(`/api/workshops/media/${id}`)));details.value=details.value.filter(d=>Number(d.workshop_id)!==Number(selected.value.id));if(detailResponse)details.value.push({...detailResponse.data,workshop_name:response.data.workshop_name});media.value=media.value.filter(m=>!f.deletedMediaIds.includes(m.id));for(const r of mediaResponses){const i=media.value.findIndex(m=>m.id===r.data.id);i<0?media.value.push(r.data):media.value[i]=r.data}const updated={...selected.value,...response.data};const i=workshops.value.findIndex(w=>w.id===updated.id);if(i>=0)workshops.value[i]=updated;selected.value=updated;edit.value=null;toast('Radionica uspješno je izmijenjena.')}catch(e){editError.value=apiError(e,'Radionicu nije moguće izmijeniti.')}finally{saving.value=false}}
async function removeWorkshop(){if(!confirm(`Želite li izbrisati radionicu „${selected.value.workshop_name}”?`))return;deleting.value=true;try{await api.delete(`/api/workshops/${selected.value.id}`);workshops.value=workshops.value.filter(w=>w.id!==selected.value.id);selected.value=null;edit.value=null;page.value=Math.min(page.value,Math.max(1,pages.value));toast('Radionica uspješno je izbrisana.')}catch(e){editError.value=apiError(e,'Radionicu nije moguće izbrisati.')}finally{deleting.value=false}}
async function openRoute(){const id=Number(route.query.id);if(!id)return;const w=workshops.value.find(x=>Number(x.id)===id);if(!w)return;periodId.value=w.reporting_period_id;await nextTick();page.value=Math.floor(filtered.value.findIndex(x=>x.id===id)/perPage)+1;selected.value=w;await nextTick();card.value?.scrollIntoView({behavior:'smooth',block:'center'})}
async function load(){loading.value=true;try{const[p,w,d,m,u]=await Promise.all([api.get('/api/reporting-periods'),api.get('/api/workshops'),api.get('/api/workshops/details'),api.get('/api/workshops/media'),api.get('/api/organizational-units')]);periods.value=p.data;workshops.value=w.data;details.value=d.data;media.value=m.data;units.value=u.data;periodId.value=periods.value[0]?.id??null;await openRoute()}catch(e){error.value=apiError(e,'Nije moguće dohvatiti radionice.')}finally{loading.value=false}}
watch([periodId,targetGroup],()=>{page.value=1;selected.value=null;cancel()});onMounted(load);onUnmounted(()=>timer&&clearTimeout(timer))
</script>
<template><main class="view"><nav class="crumbs"><RouterLink to="/istrazivanje-i-razvoj">Istraživanje i razvoj</RouterLink><span>›</span><span>Radionice</span></nav><h1>Evidencija održanih radionica</h1><p v-if="loading">Učitavanje...</p><p v-else-if="error" class="err">{{error}}</p><template v-else><section class="overview"><label>Izvještajno razdoblje<select v-model.number="periodId"><option v-for="p in periods" :key="p.id" :value="p.id">{{p.label}}</option></select></label><strong>Ukupno radionica: {{filtered.length}}</strong><ExportButton :records="filtered" file-name="radionice" /></section><div class="filters"><button v-for="g in groups" :key="g.value" :class="{active:targetGroup===g.value}" @click="targetGroup=g.value">{{g.label}}</button></div><section class="records"><header><h2>Radionice ({{filtered.length}})</h2><RouterLink class="action" to="/istrazivanje-i-razvoj/radionice/novo">Dodaj novu radionicu</RouterLink></header><div v-if="filtered.length" class="layout"><div><div class="list"><button v-for="w in shown" :key="w.id" :class="{selected:selected?.id===w.id}" @click="choose(w)"><strong>{{w.workshop_name}}</strong><span>{{display(w.workshop_leaders)}}</span></button></div><div v-if="pages>1" class="pagination"><button v-for="p in pages" :key="p" :class="{active:page===p}" @click="page=p">{{p}}</button></div></div><dl v-if="selected" ref="card" class="details"><div class="actions"><button v-if="!edit" class="action" @click="startEdit">Uredi</button><template v-else><button class="action" :disabled="saving" @click="save">{{saving?'Spremanje...':'Spremi'}}</button><button class="action" :disabled="saving" @click="cancel">Odustani</button><button class="square minus" :disabled="saving||deleting" @click="removeWorkshop">−</button></template></div><p v-if="editError" class="err">{{editError}}</p>
<div><dt>Naziv radionice</dt><dd><input v-if="edit" v-model="edit.workshop_name" class="input"><template v-else>{{selected.workshop_name}}</template></dd></div><div><dt>Voditelj/i radionice</dt><dd><input v-if="edit" v-model="edit.workshop_leaders" class="input"><template v-else>{{display(selected.workshop_leaders)}}</template></dd></div><div><dt>Sastavnica</dt><dd><select v-if="edit" v-model="edit.organizational_unit_id" class="input"><option value="">—</option><option v-for="u in units" :key="u.id" :value="u.id">{{u.short_name||u.name}}</option></select><template v-else>{{unitName(selected.organizational_unit_id)}}</template></dd></div><div><dt>Ciljana skupina</dt><dd><select v-if="edit" v-model="edit.target_group" class="input"><option v-for="g in groups.slice(1)" :key="g.value" :value="g.value">{{g.label}}</option></select><template v-else>{{groupLabel(selected.target_group)}}</template></dd></div><div><dt>Broj sudionika</dt><dd><input v-if="edit" v-model="edit.participant_count" class="input" type="number" min="0" max="9999"><template v-else>{{display(selected.participant_count)}}</template></dd></div><div><dt>Mjesto održavanja</dt><dd><input v-if="edit" v-model="edit.location" class="input"><template v-else>{{display(selected.location)}}</template></dd></div><div><dt>Datum</dt><dd><input v-if="edit" v-model="edit.held_on" class="input" type="date"><template v-else>{{date(selected.held_on)}}</template></dd></div><div><dt>Trajanje (sati)</dt><dd><input v-if="edit" v-model="edit.duration_hours" class="input" type="number" min="0" max="999"><template v-else>{{display(selected.duration_hours)}}</template></dd></div><div><dt>Opis sadržaja</dt><dd><textarea v-if="edit" v-model="edit.content_description" class="input"></textarea><template v-else>{{display(selected.content_description)}}</template></dd></div><div><dt>Potpis voditelja</dt><dd><a v-if="url(selected.leader_signature_storage_path)" :href="url(selected.leader_signature_storage_path)" target="_blank">{{selected.leader_signature_file_name}}</a><template v-else>—</template></dd></div><div><dt>Medijska poveznica</dt><dd><input v-if="edit" v-model="edit.media_link" class="input"><a v-else-if="url(selected.media_link)" :href="url(selected.media_link)" target="_blank">{{selected.media_link}}</a><template v-else>{{display(selected.media_link)}}</template></dd></div><div><dt>Napomena</dt><dd><textarea v-if="edit" v-model="edit.notes" class="input"></textarea><template v-else>{{display(selected.notes)}}</template></dd></div>
<section class="related"><header><h3>Detaljni opis radionice</h3><button v-if="edit" class="square plus" :class="{active:edit.detail}" @click="toggleDetail">+</button></header><p v-if="!(edit?edit.detail:selectedDetails)">Detaljni opis nije dodan.</p><article v-else class="detail-grid"><template v-if="edit"><label>Ciljevi<textarea v-model="edit.detail.goals" class="input"></textarea></label><label>Ishodi učenja<textarea v-model="edit.detail.learning_outcomes" class="input"></textarea></label><label>Metode rada<textarea v-model="edit.detail.work_methods" class="input"></textarea></label><label>Materijali i resursi<textarea v-model="edit.detail.materials_resources" class="input"></textarea></label><label>Evaluacija<textarea v-model="edit.detail.evaluation" class="input"></textarea></label></template><template v-else><span><b>Ciljevi:</b> {{display(selectedDetails.goals)}}</span><span><b>Ishodi:</b> {{display(selectedDetails.learning_outcomes)}}</span><span><b>Metode:</b> {{display(selectedDetails.work_methods)}}</span><span><b>Materijali:</b> {{display(selectedDetails.materials_resources)}}</span><span><b>Evaluacija:</b> {{display(selectedDetails.evaluation)}}</span></template></article></section>
<section class="related"><header><h3>Linkovi na medijske objave</h3><button v-if="edit" class="square plus" @click="addMedia">+</button></header><p v-if="!(edit?edit.media:selectedMedia).length">Nema medijskih objava.</p><article v-for="m in edit?edit.media:selectedMedia" :key="m.id||m.temporaryId" class="media-card"><button v-if="edit" class="square minus floating" @click="removeMedia(m)">−</button><template v-if="edit"><label>Naziv radionice<input v-model="m.workshop_name" class="input"></label><label>Vrsta medija<input v-model="m.media_type" class="input"></label><label>Link<input v-model="m.media_link" class="input"></label><label>Datum objave<input v-model="m.published_on" class="input" type="date"></label></template><template v-else><strong>{{m.workshop_name}}</strong><span>{{display(m.media_type)}}</span><a :href="url(m.media_link)" target="_blank">{{m.media_link}}</a><span>{{date(m.published_on)}}</span></template></article></section></dl></div><p v-else>Nema radionica.</p></section>
<section class="summaries"><h2>Detaljni opis radionica</h2><div class="table"><table><thead><tr><th>Broj</th><th>Naziv radionice</th><th>Ciljevi</th><th>Ishodi učenja</th><th>Metode rada</th><th>Materijali/resursi</th><th>Evaluacija</th></tr></thead><tbody><tr v-for="(d,i) in periodDetails" :key="d.id"><td>{{i+1}}</td><td>{{d.workshop_name}}</td><td>{{display(d.goals)}}</td><td>{{display(d.learning_outcomes)}}</td><td>{{display(d.work_methods)}}</td><td>{{display(d.materials_resources)}}</td><td>{{display(d.evaluation)}}</td></tr></tbody></table></div><h2>Sažetak medijskih objava</h2><div class="table"><table><thead><tr><th>Broj</th><th>Naziv radionice</th><th>Vrsta medija</th><th>Link</th><th>Datum objave</th></tr></thead><tbody><tr v-for="(m,i) in periodMedia" :key="m.id"><td>{{i+1}}</td><td>{{m.workshop_name}}</td><td>{{display(m.media_type)}}</td><td><a :href="url(m.media_link)" target="_blank">{{m.media_link}}</a></td><td>{{date(m.published_on)}}</td></tr></tbody></table></div></section></template><div v-if="success" class="snackbar">{{success}}</div></main></template>
<style scoped>.view{min-height:calc(100vh - 112px);padding:34px clamp(32px,5vw,128px) 90px;background:rgb(var(--v-theme-background));color:rgb(var(--v-theme-on-background))}.crumbs,.overview,.records>header,.filters,.actions,.related header{display:flex;align-items:center}.crumbs{gap:10px;color:rgb(var(--v-theme-muted))}.crumbs a{color:inherit}.crumbs a:hover{color:rgb(var(--v-theme-primary))}h1{margin:18px 0;color:rgb(var(--v-theme-primary));font-weight:400}h2{font-weight:400}.overview,.records>header{justify-content:space-between}.overview{margin-top:36px}.overview label{display:grid;gap:8px;color:rgb(var(--v-theme-primary));font-weight:700}select,.input{padding:9px 12px;border:1px solid rgb(var(--v-theme-category-border));border-radius:7px;background:rgb(var(--v-theme-surface));color:rgb(var(--v-theme-on-surface));font:inherit}.filters{flex-wrap:wrap;gap:10px;margin-top:42px}.filters button,.action{padding:9px 15px;border:1px solid rgb(var(--v-theme-category-border));border-radius:7px;background:rgb(var(--v-theme-surface));color:rgb(var(--v-theme-on-surface));cursor:pointer}.filters button{border-radius:999px}.filters .active,.filters button:hover,.action:hover,.plus:hover,.plus.active{background:rgb(var(--v-theme-primary));color:rgb(var(--v-theme-on-primary))}.records,.summaries{margin-top:70px}.layout{display:grid;grid-template-columns:minmax(280px,.85fr) minmax(500px,1.15fr);gap:clamp(44px,8vw,140px);align-items:start;margin-top:30px}.list{display:grid;gap:5px}.list button{display:grid;gap:4px;padding:13px 16px;border:0;border-radius:7px;background:transparent;color:rgb(var(--v-theme-membership-link));text-align:left}.list button span{color:rgb(var(--v-theme-muted))}.list button:hover,.list button.selected{background:rgba(var(--v-theme-primary),.1)}.pagination{display:flex;justify-content:center;gap:5px}.pagination button{width:30px;height:30px;border:0;border-radius:6px}.pagination .active{background:rgb(var(--v-theme-primary));color:rgb(var(--v-theme-on-primary))}.details{display:grid;gap:10px;margin:0;padding:clamp(28px,3vw,48px);border:1px solid rgb(var(--v-theme-category-border));border-radius:10px;background:rgb(var(--v-theme-category-card));color:rgb(var(--v-theme-on-category-card))}.details>div:not(.actions){display:grid;grid-template-columns:minmax(160px,.9fr) minmax(0,1.1fr);gap:22px}.details dd{margin:0}.actions{justify-content:flex-end;gap:8px}.input{width:100%;box-sizing:border-box}.square{display:grid;width:30px;height:30px;padding:0;place-items:center;border:1px solid rgb(var(--v-theme-on-surface));border-radius:6px;background:rgb(var(--v-theme-surface));color:rgb(var(--v-theme-on-surface));font-size:1.2rem}.minus:hover{background:rgb(var(--v-theme-error));color:#fff}.related{display:grid;gap:14px;margin-top:18px;padding-top:20px;border-top:1px solid rgb(var(--v-theme-category-border))}.related header{gap:10px}.related h3{margin:0}.related article{position:relative;display:grid;gap:12px;padding:20px;border:1px solid rgb(var(--v-theme-category-border));border-radius:9px}.detail-grid,.media-card{grid-template-columns:repeat(2,minmax(0,1fr))}.related label{display:grid;gap:6px}.media-card:has(.floating){padding-top:52px}.floating{position:absolute;top:10px;right:10px}.summaries h2{margin-top:50px}.table{overflow-x:auto;border-radius:10px}.table table{width:100%;border-collapse:collapse}.table th,.table td{padding:13px 15px;border:1px solid rgb(var(--v-theme-table-border));text-align:left}.table th{background:rgb(var(--v-theme-category-card));color:rgb(var(--v-theme-on-category-card))}a{color:rgb(var(--v-theme-evidence-link))}.err{color:rgb(var(--v-theme-error))}.snackbar{position:fixed;right:28px;bottom:28px;padding:14px 18px;border:1px solid #62a957;border-radius:7px;background:#b8f5ae;color:#1f5525}@media(max-width:900px){.layout{grid-template-columns:1fr}}@media(max-width:650px){.view{padding:28px 20px}.overview,.records>header{align-items:stretch;flex-direction:column;gap:18px}.details>div:not(.actions),.detail-grid,.media-card{grid-template-columns:1fr}}</style>
